      pt: ["Comprimento: 200 km.", "Bacia hidrográfica: 20.000 km².", "Barragem: Manyame (1976).", "Área do lago: 20 km².", "Abastecimento de água para 2 milhões de pessoas.", "Área de irrigação: 10.000 hectares."],
      fr: ["Longueur : 200 km.", "Bassin versant : 20 000 km².", "Barrage : barrage de Manyame (1976).", "Superficie du lac : 20 km².", "Approvisionnement en eau pour 2 millions de personnes.", "Surface irriguée : 10 000 hectares."],
